pairs(s,[U],[('preferer','Предпочитать из вариантов'),('adorer','Обожать занятие'),('detester','Очень не любить занятие')],'Вы различили предпочтение и два сильных отношения.','Предпочтение выделяет вариант, обожать выражает сильное положительное отношение, очень не любить — отрицательное.')
listen(s,[A],['aller','cinema','preferer','parc','parce-que','calme','daccord','se-promener','midi'],['parc','calme','midi'],'Первая и третья реплики принадлежат одному человеку, вторая — собеседнику. Какие место и время согласованы и какую причину предпочтения назвал собеседник?','— On peut aller au cinéma ? — Je préfère le parc parce que le parc est calme. — D’accord. On peut se promener au parc à midi.','— о(н) пё алэ о синэма́? — жё прэфэр лё парк парс кё лё парк э ка́льм. — дако́р. о(н) пё сё промнэ о парк а миди́.',['Парк; полдень; в парке тихо','Кино; полдень; кино дешевле','Парк; девять; в парке тихо'],0,'Согласованы парк и полдень; названная причина — в парке тихо.','Первое предложение о кино не стало итогом. Полдень назван в последней реплике, а тишина — в объяснении предпочтения.')
choose(s,'vocabulary',[A],['choisir','parc','parce-que','calme','cinema','cher','preferer'],['parce-que','calme'],'Нужно сказать «Я выбираю парк, потому что в парке тихо». Что подходит?',ru('Сохраните выбранный вариант и прямо указанную причину.'),[fr('Je choisis le parc parce que le cinéma est cher.','жё шуази лё парк парс кё лё синэма э шэ́р'),fr('Je choisis le parc parce que le parc est calme.','жё шуази лё парк парс кё лё парк э ка́льм'),fr('Je préfère le cinéma.','жё прэфэр лё синэма́')],1,'Выбран парк с причиной в парке тихо.','Дорогой кинотеатр задаёт другую причину, предпочтение кино меняет вариант. В условии нужны парк и тишина.')
grammar(fill(s,[A],['cafe-lieu','bruyant','parc'],[],'Восстановите связку второго варианта в сравнении по шуму.','Le café est plus bruyant ','лё кафэ э плю брюийа́(н)',' le parc.','лё па́рк',[fr('que','кё'),fr('et','э')],0,'Le café est plus bruyant que le parc.','лё кафэ э плю брюийа(н) кё лё па́рк.','Сохранена связка сравнения с парком.','В этом образце второй вариант вводится связкой чем, а не простым и.'))
order(s,[U,A],['preferer','se-promener','parc','parce-que','calme'],[],'Соберите «Я предпочитаю гулять в парке, потому что в парке тихо». Сначала предпочтение с занятием, затем причина.',[('Je préfère','жё прэфэ́р'),('me promener au parc','мё промнэ о па́рк'),('parce que','парс кё'),('le parc est calme.','лё парк э ка́льм')],'Je préfère me promener au parc parce que le parc est calme.','жё прэфэр мё промнэ о парк парс кё лё парк э ка́льм.','Получилось предпочтение с прямо названной причиной.','Сначала поставьте предпочитаю и прогулку в парке, затем потому что и сообщение о тишине.')
choose(s,'reading',[A],['aimer-activite','ecouter','musique','aller','cafe-lieu','preferer','parc','parce-que','moins','bruyant','daccord','se-promener'],['daccord','parc','se-promener'],'Первая и третья реплики принадлежат одному человеку, вторая — собеседнику. Какое занятие становится общей договорённостью?',fr('— J’aime écouter de la musique. On peut aller au café ? — Je préfère le parc parce que le parc est moins bruyant que le café. — D’accord. On peut se promener au parc.','— жэм экутэ дё ла мюзи́к. о(н) пё алэ о кафэ́? — жё прэфэр лё парк парс кё лё парк э муэ(н) брюийа(н) кё лё кафэ́. — дако́р. о(н) пё сё промнэ о па́рк.'),['Поход в кафе','Прослушивание музыки','Прогулка в парке'],2,'Общая договорённость — прогулка в парке.','Первоначальный вариант кафе заменён после ответа собеседника. Любовь к музыке не является итоговым совместным планом.')
page(s,[('Предпочтения участников',['Любимое занятие одного участника может отличаться от предпочтения другого. Окончательная договорённость читается по принятию конкретного предложения.'],[W['preferer']['example']]),('Сравнение и причина',['Цена, шум и предпочтение — разные сведения. Причину выбора связывает с ним явная связка; соседнее сообщение не становится причиной автоматически.'],[W['parce-que']['example'],W['moins']['example']]),('Собрать объяснение',['В короткой реплике можно назвать выбранное занятие и простую причину. Все обязательные формы уже были показаны, свободно печатать текст не нужно.'],[ex('Je préfère me promener au parc parce que le parc est calme.','Я предпочитаю гулять в парке, потому что в парке тихо.','жё прэфэр мё промнэ о парк парс кё лё парк э ка́льм')])])

for s in S:
 required=list(dict.fromkeys(w for t in s['tasks'] for w in t['vocabulary_ids']))
 required+=list(dict.fromkeys(w for i in s['introductions'] for w in i['vocabulary_ids']))
 s['vocabulary']=[w for w in s['vocabulary'] if w['id'] in required]
 present={w['id'] for w in s['vocabulary']}
 for w in required:
  if w not in present:s['vocabulary'].append(copy.deepcopy(W[w]));present.add(w)
 s['skills']=list(dict.fromkeys(t['skill'] for t in s['tasks']))
NOTES={w['fr']:w['transcription_ru'] for w in W.values()}
NOTES.update({W[w]['fr'].capitalize():W[w]['transcription_ru'] for w in FIRST})

def annotate(v):
 if isinstance(v,list):
  for x in v:annotate(x)
 if not isinstance(v,dict):return
 supported=('correct' in v or 'before_task_id' in v or 'instruction' in v or 'description' in v or 'paragraphs' in v)
 if supported:
  text=(v.get('prompt',{}).get('text','') if v.get('prompt',{}).get('text_lang')=='ru' else '')+' '+' '.join(v.get(k,'') for k in ['instruction','hint','correct','incorrect','text','description','heading'])+' '+' '.join(v.get('paragraphs',[]))
  ns=v.get('pronunciation_notes',[])
  for f,p in NOTES.items():
   if re.search(r'(?<![A-Za-zÀ-ÿŒœ])'+re.escape(f)+r'(?![A-Za-zÀ-ÿŒœ])',text) and not any(n['fr']==f for n in ns):ns.append(dict(fr=f,transcription_ru=p))
  if ns:v['pronunciation_notes']=ns
 for x in list(v.values()):annotate(x)
unit=dict(id=plan['id'],level='A1',slug=plan['slug'],title=plan['title'],order=plan['order'],summary='Любимые занятия, явное предпочтение, сравнение двух вариантов и прямо названная причина совместного выбора.',learning_outcomes=['Различать любовь к занятию, сильное положительное и отрицательное отношение.','Находить прямо названное предпочтение среди нескольких любимых занятий.','Понимать направление сравнения двух вариантов по одному признаку.','Находить причину, прямо связанную с выбором.','Выбирать и собирать объяснение предпочтения и итоговой договорённости.'])
