D=dict(unit_id=plan['id'],package_file=target.name,session_ids=[s['id'] for s in S],new_lexemes=[dict(**{k:W[w][k] for k in ['id','lexeme_key','fr','ru','transcription_ru']},first_session_id=S[n-1]['id']) for w,n in FIRST.items()],reused_lexeme_keys=sorted({w['lexeme_key'] for s in S for w in s['vocabulary'] if w['id'] in OLD}),objective_coverage=coverage,
 review_targets_for_next_unit=[dict(lexeme_key=W[w]['lexeme_key'],reason=r) for w,r in [('preferer','Вернуть предпочтение отдельно от намерения в следующей теме планов.'),('choisir','Повторить конкретный выбор до рассказа о будущем действии.'),('parce-que','Сохранить прямо названную причину простого решения.'),('aimer-activite','Повторить знакомое отношение к занятиям с прежним ключом.'),('adorer','Вернуть сильное положительное отношение коротким повторением.'),('detester','Повторить отрицательное отношение отдельно от отказа на конкретное время.'),('moins','Сохранить направление менее при сравнении двух вариантов.'),('bruyant','Вернуть признак места, не приписывая его всем кафе.'),('facile','Повторить нетрудное задание в понятной учебной ситуации.')]],
 checks=dict(json_parsed=False,schema_validated=False,site_preview_passed=False,browser_audio_checked=False,language_reviewed_by_human=False),
 open_issues=['До импорта целевая база должна содержать A1-U15-L05; пакет не создаёт внешнюю зависимость.','Редактору проверить естественность французских выражений отношения, выбранных сравнений, причин и приблизительные русские транскрипции.','Прослушать браузерную озвучку, особенно adorer/détester/préférer, шум, менее и связку причины. Время аудио и занятий пока не измерено.','Выполнить предпросмотр и пробное прохождение: сильное отношение и явное предпочтение, направление сравнения, явно названная причина и итоговый общий выбор.'],
 progress=dict(current_unit=plan['id'],prepared_session_ids=[s['id'] for s in S],user_accepted_session_ids=[],remaining_session_ids=[],next_unit_not_started='A1-U17',next_unit_title='Планы на завтра',previous_unit='A1-U15',previous_unit_advance_authorized=True,previous_unit_import_confirmed=False),
 scope_notes=['Команда «Следующий этап» разрешает подготовку A1-U16. Принятие и импорт предыдущих пакетов не подтверждены; повторение использует полные объекты подготовленных пакетов.','Новые значения распределены как два, одно, два, три и ноль. В пятом занятии нового обязательного материала нет.','Aimer с занятием сохраняет прежний ключ fr:aimer:enjoy-activity. Карточки отношения к еде с отдельными узкими значениями не переписываются.','Adorer усиливает положительное отношение, détester выражает сильное отрицательное. Описываются вымышленные предпочтения занятий, не оценка людей.','Préférer выделяет один вариант из уже названных. Человек может любить оба занятия; порядок упоминания и одно слово обожаю не заменяют явное предпочтение.','Plus/moins с que показаны на сравнении двух вариантов по одному признаку. Прежний ключ дорогой сохранён; шум и цена не смешиваются.','Свойства парка, кафе и кинотеатра вымышленные. Они не объявляются общими фактами о таких местах, реальных ценах или доступности.','Parce que прямо вводит причину выбора. Соседнее положительное сообщение не становится причиной автоматически. Выбирать и предпочитать различаются по функции в тексте.','Facile введено как нетрудное учебное упражнение; реальная оценка способностей учащегося не делается. Номера упражнений обозначают задания, а не порядок карточек ответа.','В L01 повторён план на хорошую погоду A1-U15; в L03 и L04 — волосы и прямо названные черты близких людей A1-U13.','Роли в диалогах заданы порядком реплик. Общая договорённость определяется согласием на конкретный вариант, а не первым предложением или личным любимым занятием.','Новые сложные причинные конструкции, инверсия и полное спряжение не вводятся; используются короткие показанные личные формы и повтор известных рамок предложения.','Все записи, сравнения и переговоры вымышленные. Реальные заведения, цены и внешние сервисы не нужны для ответа.','Пакет содержит только текущую тему, без levels и curricula. Основной реестр, прежние пакеты и база сайта не изменялись.'])

